//! Bitmaps of the fonts and logos in `deck/assets/`, generated by
//! `tools/assets`. Do not edit; rerun
//! `cargo run --manifest-path tools/assets/Cargo.toml` instead.

use crate::draw::{Font, Image};

/// IBM Plex Mono for body text: ASCII and `…`.
pub(crate) const BODY: Font = Font {
    chars: " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~…",
    width: 7,
    height: 13,
    baseline: 10,
    data: include_bytes!("../assets/gen/body.bin"),
};

/// DotGothic16 at twice its pixel size, for big numbers.
pub(crate) const NUMERAL: Font = Font {
    chars: "0123456789-",
    width: 16,
    height: 27,
    baseline: 26,
    data: include_bytes!("../assets/gen/numeral.bin"),
};

/// DotGothic16's `%` at its pixel size, after big numbers.
pub(crate) const PERCENT: Font = Font {
    chars: "%",
    width: 8,
    height: 14,
    baseline: 13,
    data: include_bytes!("../assets/gen/percent.bin"),
};

/// Ark Pixel kanji at their 12 px pixel size, the height of body text.
pub(crate) const KANJI: Font = Font {
    chars: "稼働待機今",
    width: 12,
    height: 11,
    baseline: 9,
    data: include_bytes!("../assets/gen/kanji.bin"),
};

/// Claude's logo, for Claude Code.
pub(crate) const CLAUDE: Image = Image {
    width: 32,
    height: 32,
    data: include_bytes!("../assets/gen/claude.bin"),
};

/// pi's logo, from the press kit at <https://pi.dev/press-kit>.
pub(crate) const PI: Image = Image {
    width: 32,
    height: 32,
    data: include_bytes!("../assets/gen/pi.bin"),
};

/// OpenAI's logo, for Codex.
pub(crate) const OPENAI: Image = Image {
    width: 32,
    height: 32,
    data: include_bytes!("../assets/gen/openai.bin"),
};
